package com.nexushr.controller; import com.nexushr.dto.EmployeeDtos.*; import com.nexushr.service.EmployeeService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/employees") public class EmployeeController {final EmployeeService s;public EmployeeController(EmployeeService s){this.s=s;} @GetMapping @PreAuthorize("hasAnyRole('ADMIN','HR')") public List<EmployeeView> all(){return s.all();} @GetMapping("/{id}") public EmployeeView one(@PathVariable UUID id){return s.one(id);} @PostMapping @PreAuthorize("hasAnyRole('ADMIN','HR')") public EmployeeView create(@RequestBody CreateEmployee x){return s.create(x);} @PutMapping("/{id}") @PreAuthorize("hasAnyRole('ADMIN','HR')") public EmployeeView update(@PathVariable UUID id,@RequestBody UpdateEmployee x){return s.update(id,x);} @GetMapping("/me") public EmployeeView me(java.security.Principal p){return s.one(s.current(p.getName()).getId());}}
